def get_rot(g, degrees):
    if degrees == 0:
        return [row[:] for row in g]
    elif degrees == 90:
        return rotate_90(g)
    elif degrees == 180:
        return rotate_90(rotate_90(g))
    elif degrees == 270:
        return rotate_90(rotate_90(rotate_90(g)))

def rotate_90(g):
    n = len(g)
    return [[g[n - 1 - c][r] for c in range(n)] for r in range(n)]

def transform(grid):
    height, width = len(grid), len(grid[0])
    final = [[0] * (width * 2) for _ in range(height * 2)]

    # TL = 0°
    for r in range(height):
        for c in range(width):
            final[r][c] = grid[r][c]

    # TR = 90°
    rot90 = get_rot(grid, 90)
    for r in range(height):
        for c in range(width):
            final[r][width + c] = rot90[r][c]

    # BL = 270°
    rot270 = get_rot(grid, 270)
    for r in range(height):
        for c in range(width):
            final[height + r][c] = rot270[r][c]

    # BR = 180°
    rot180 = get_rot(grid, 180)
    for r in range(height):
        for c in range(width):
            final[height + r][width + c] = rot180[r][c]

    return final

